<?php
$q=trim((string)get('q'));$filter=(string)get('status');
$sql='SELECT w.*,u.email FROM data_warga w LEFT JOIN users u ON u.id=w.user_id WHERE (w.nama_lengkap LIKE ? OR w.nik LIKE ? OR w.alamat LIKE ?)';$params=['%'.$q.'%','%'.$q.'%','%'.$q.'%'];
if(in_array($filter,['aktif','nonaktif','pindah','meninggal'],true)){$sql.=' AND w.status=?';$params[]=$filter;}$sql.=' ORDER BY w.nama_lengkap LIMIT 300';$stmt=db()->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();
$edit=null;if(get('edit')){$s=db()->prepare('SELECT * FROM data_warga WHERE id=?');$s->execute([(int)get('edit')]);$edit=$s->fetch();}
?>
<div class="page-heading"><div><h1>Data Warga</h1><p>Kelola data kependudukan dan informasi keluarga di lingkungan RT.</p></div><a class="btn btn-army" href="<?= e(url('data-warga',['new'=>1])) ?>"><i class="bi bi-person-plus me-2"></i>Tambah Warga</a></div>
<?php if(get('new') || $edit): ?><section class="panel-card mb-4"><div class="panel-card-header"><h2 class="panel-title"><?= $edit?'Ubah Data Warga':'Tambah Warga Baru' ?></h2><a class="text-link" href="<?= e(url('data-warga')) ?>">Tutup</a></div><div class="panel-card-body"><form method="post" action="index.php" class="row g-3" data-disable-submit><?= csrf_field() ?><input type="hidden" name="action" value="save_warga"><input type="hidden" name="return_page" value="data-warga"><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><div class="col-md-4"><label class="form-label">NIK</label><input class="form-control" name="nik" maxlength="16" pattern="[0-9]{16}" value="<?= e($edit['nik']??'') ?>" required></div><div class="col-md-4"><label class="form-label">Nomor KK</label><input class="form-control" name="no_kk" maxlength="16" value="<?= e($edit['no_kk']??'') ?>"></div><div class="col-md-4"><label class="form-label">Nama lengkap</label><input class="form-control" name="nama_lengkap" value="<?= e($edit['nama_lengkap']??'') ?>" required></div><div class="col-md-3"><label class="form-label">Jenis kelamin</label><select class="form-select" name="jenis_kelamin"><option value="">Belum dipilih</option><option value="laki-laki" <?= ($edit['jenis_kelamin']??'')==='laki-laki'?'selected':'' ?>>Laki-laki</option><option value="perempuan" <?= ($edit['jenis_kelamin']??'')==='perempuan'?'selected':'' ?>>Perempuan</option></select></div><div class="col-md-3"><label class="form-label">Tempat lahir</label><input class="form-control" name="tempat_lahir" value="<?= e($edit['tempat_lahir']??'') ?>"></div><div class="col-md-3"><label class="form-label">Tanggal lahir</label><input class="form-control" type="date" name="tanggal_lahir" value="<?= e($edit['tanggal_lahir']??'') ?>"></div><div class="col-md-3"><label class="form-label">Status keluarga</label><select class="form-select" name="status_keluarga"><option value="">Pilih</option><?php foreach(['Kepala Keluarga','Istri','Suami','Anak','Orang Tua','Lainnya'] as $v): ?><option <?= ($edit['status_keluarga']??'')===$v?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">RT</label><input class="form-control" name="rt" value="<?= e($edit['rt']??'') ?>"></div><div class="col-md-3"><label class="form-label">RW</label><input class="form-control" name="rw" value="<?= e($edit['rw']??'') ?>"></div><div class="col-md-3"><label class="form-label">Pekerjaan</label><input class="form-control" name="pekerjaan" value="<?= e($edit['pekerjaan']??'') ?>"></div><div class="col-md-3"><label class="form-label">Nomor HP</label><input class="form-control" name="no_hp" value="<?= e($edit['no_hp']??'') ?>"></div><div class="col-md-9"><label class="form-label">Alamat lengkap</label><input class="form-control" name="alamat" value="<?= e($edit['alamat']??'') ?>" required></div><div class="col-md-3"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['aktif','nonaktif','pindah','meninggal'] as $v): ?><option value="<?= $v ?>" <?= ($edit['status']??'aktif')===$v?'selected':'' ?>><?= ucfirst($v) ?></option><?php endforeach; ?></select></div><div class="col-12 d-flex gap-2 justify-content-end"><a class="btn btn-outline-secondary" href="<?= e(url('data-warga')) ?>">Batal</a><button class="btn btn-army" type="submit">Simpan Data</button></div></form></div></section><?php endif; ?>
<section class="panel-card"><div class="data-toolbar"><form class="d-flex flex-wrap gap-2 flex-grow-1" method="get"><input type="hidden" name="page" value="data-warga"><input class="form-control" style="max-width:360px" name="q" value="<?= e($q) ?>" placeholder="Cari nama, NIK, atau alamat"><select class="form-select" style="max-width:190px" name="status"><option value="">Semua status</option><?php foreach(['aktif','nonaktif','pindah','meninggal'] as $v): ?><option value="<?= $v ?>" <?= $filter===$v?'selected':'' ?>><?= ucfirst($v) ?></option><?php endforeach; ?></select><button class="btn btn-outline-army">Cari</button></form><span class="text-muted-2"><?= count($rows) ?> data</span></div><div class="table-responsive"><table class="table"><thead><tr><th>NIK</th><th>Nama</th><th>Jenis Kelamin</th><th>Alamat</th><th>Status Keluarga</th><th>Kontak</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="8"><div class="empty-state"><i class="bi bi-people"></i><strong>Data warga belum tersedia</strong><span>Tambahkan data warga untuk mulai mengelola kependudukan.</span></div></td></tr><?php else: foreach($rows as $w): ?><tr><td class="text-nowrap"><code><?= e($w['nik']) ?></code></td><td><strong><?= e($w['nama_lengkap']) ?></strong><?php if($w['email']): ?><small class="d-block text-muted-2"><?= e($w['email']) ?></small><?php endif; ?></td><td><?= e(ucwords($w['jenis_kelamin']??'-')) ?></td><td><?= e($w['alamat']) ?></td><td><?= e($w['status_keluarga']??'-') ?></td><td><?= e($w['no_hp']??'-') ?></td><td><?= status_badge($w['status']) ?></td><td><div class="d-flex gap-1"><a class="btn btn-sm btn-outline-army" href="<?= e(url('data-warga',['edit'=>$w['id']])) ?>">Edit</a><?php if($w['status']==='aktif'): ?><form method="post" action="index.php" class="m-0"><?= csrf_field() ?><input type="hidden" name="action" value="set_warga_status"><input type="hidden" name="return_page" value="data-warga"><input type="hidden" name="id" value="<?= $w['id'] ?>"><input type="hidden" name="status" value="nonaktif"><button class="btn btn-sm btn-outline-secondary" data-confirm="Nonaktifkan data warga ini?">Nonaktifkan</button></form><?php endif; ?></div></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
